class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def tree_to_level_order(root):
    if root is None:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node is None:
            result.append(None)
            continue
        result.append(node.val)
        queue.append(node.left)
        queue.append(node.right)
    while result and result[-1] is None:
        result.pop()
    return result


def recover_tree(root_arr):
    root = build_tree(root_arr)

    first = [None]
    second = [None]
    prev = [None]

    def inorder(node):
        if node is None:
            return
        inorder(node.left)
        if prev[0] and prev[0].val > node.val:
            if first[0] is None:
                first[0] = prev[0]
            second[0] = node
        prev[0] = node
        inorder(node.right)

    inorder(root)
    first[0].val, second[0].val = second[0].val, first[0].val
    return tree_to_level_order(root)

